// ===== EDIT THIS: gateway + central station settings =====
flow.set('dc09cfg', {
    host: '192.168.250.100',      // DC-09 server IP  (demo: local mock receiver)
    port: 8090,            // DC-09 server TCP port
    account: '1234',        // #acct  3-16 HEX chars
    prefix: '0',            // Lpref  1-6 HEX chars ('0' = none)
    receiver: '',           // Rrcvr  1-6 HEX chars, '' = omit R field
    timestamp: true,        // append GMT timestamp (required later for encryption)
    sendText: true,         // append [I<point name>] extended data
    retryTimeoutMs: 20000,  // DC-09 recommended 20 s (allowed 5-60 s)
    maxAttempts: 3,         // DC-09 recommended 3
    maxQueue: 500
});

// ===== EDIT THIS: BACnet point -> Contact ID map =====
// key = <objectType>:<instance>  (add device id later if you poll several devices)
// binary: alarm when value == alarmValue (default 1/active)
// analog: alarm when value >= high, restore when value < high - deadband
flow.set('points', {
    'BI:1':  { name:'Fire Alarm Zone 1',     code:'110', group:'00', zone:'001', type:'binary' },
    'BI:2':  { name:'Smoke Detector Zone 2', code:'111', group:'00', zone:'002', type:'binary' },
    'BI:3':  { name:'Fault Zone 3',          code:'380', group:'00', zone:'003', type:'binary' },
    'BI:7':  { name:'Gas Detected Zone 7',   code:'151', group:'00', zone:'007', type:'binary' },
    'BI:20': { name:'AC Power Loss',         code:'301', group:'00', zone:'000', type:'binary' },
    'AI:6':  { name:'High Temp Zone 6',      code:'158', group:'00', zone:'006', type:'analog', high:35, deadband:2 }
});
node.status({fill:'green',shape:'dot',text:'config loaded'});
return null;

// Input: msg.payload = { objectType:'BI'|'AI'|..., instance:Number, value:Number|Boolean }
// Output: Contact ID event on state change only (alarm -> Q=1, restore -> Q=3)
const points = flow.get('points') || {};
const p = msg.payload || {};
const key = String(p.objectType).toUpperCase() + ':' + p.instance;
const pt = points[key];
if (!pt) { node.warn('Unmapped BACnet point ' + key); return null; }

const v = Number(p.value === true ? 1 : p.value === false ? 0 : p.value);
const last = context.get('state') || {};
const wasAlarm = !!last[key];
let isAlarm;
if (pt.type === 'analog') {
    isAlarm = wasAlarm ? v >= (pt.high - (pt.deadband || 0)) : v >= pt.high;
} else {
    isAlarm = v === Number(pt.alarmValue ?? 1);
}
if (isAlarm === wasAlarm && last[key] !== undefined) return null;   // no change
const first = last[key] === undefined;
last[key] = isAlarm; context.set('state', last);
if (first && !isAlarm) return null;   // first read is normal -> nothing to report

node.status({fill: isAlarm ? 'red' : 'green', shape:'dot', text: key + (isAlarm ? ' ALARM' : ' normal')});
msg.topic = 'event';
msg.payload = { q: isAlarm ? '1' : '3', code: pt.code, group: pt.group || '00', zone: pt.zone, text: pt.name, point: key, value: v };
return msg;

function crc16(s){let c=0;for(const b of Buffer.from(s,'latin1')){c^=b;for(let i=0;i<8;i++)c=(c&1)?(c>>>1)^0xA001:c>>>1;}return c.toString(16).toUpperCase().padStart(4,'0');}
function hex(v,w){return v.toString(16).toUpperCase().padStart(w,'0');}
function gmt(offsetMs){const d=new Date(Date.now()+(offsetMs||0));const p=x=>String(x).padStart(2,'0');return '_'+p(d.getUTCHours())+':'+p(d.getUTCMinutes())+':'+p(d.getUTCSeconds())+','+p(d.getUTCMonth()+1)+'-'+p(d.getUTCDate())+'-'+d.getUTCFullYear();}
function frame(body){return '\n'+crc16(body)+'0'+hex(body.length,3)+body+'\r';}
// DC-09 body regex: "id" seq [Rrcvr] Lpref [#acct|A0] [data] [ext]... [timestamp]
const RX=/^"(\*?[A-Z0-9-]+)"(\d{4})(R[0-9A-F]{1,6})?(L[0-9A-F]{1,6})(#[0-9A-F]{3,16}|A0)?\[([^\]]*)\]((?:\[[^\]]*\])*)(_\d\d:\d\d:\d\d,\d\d-\d\d-\d{4})?$/i;
function unwrap(raw){const s=String(raw).replace(/^[\r\n]+/,'').replace(/[\r\n]+$/,'');
  if(s.length<9)return {ok:false,err:'too short',raw:s};
  const crc=s.slice(0,4).toUpperCase(),len=s.slice(4,8),body=s.slice(8);
  if(crc16(body)!==crc)return {ok:false,err:'CRC mismatch (got '+crc+', calc '+crc16(body)+')',raw:s};
  if(parseInt(len,16)!==body.length)return {ok:false,err:'length mismatch',raw:s};
  const m=body.match(RX); if(!m)return {ok:false,err:'malformed frame',raw:s};
  return {ok:true,id:m[1],seq:m[2],rcvr:m[3]||'',pref:m[4],acct:m[5]||'',data:m[6],ext:m[7]||'',ts:m[8]||'',body};}

// ===== DC-09 sender: queue, frame, retry, ACK/NAK/DUH =====
// topics in:  'event' (payload {q,code,group,zone,text}), 'heartbeat', 'response' (from tcp request), 'reset'
// out1 -> tcp request   out2 -> log
const cfg = flow.get('dc09cfg');
if (!cfg) { node.error('dc09cfg not set - run CONFIG'); return null; }
const st = context.get('st') || { queue: [], inflight: null, offset: 0 };
const log = (lvl, text, extra) => node.send([null, { topic: lvl, payload: Object.assign({ time: new Date().toISOString(), text }, extra || {}) }]);

function nextSeq() { let s = (context.get('seq') || 0) + 1; if (s > 9999) s = 1; context.set('seq', s); return String(s).padStart(4, '0'); }
function clean(t) { return String(t || '').replace(/[\[\]|]/g, ' ').slice(0, 64); }
function build(it) {
    const R = cfg.receiver ? 'R' + cfg.receiver : '';
    const L = 'L' + (cfg.prefix || '0');
    let body;
    if (it.type === 'NULL') {
        body = '"NULL"0000' + R + L + '#' + cfg.account + '[]';
    } else {
        body = '"ADM-CID"' + it.seq + R + L + '#' + cfg.account +
               '[#' + cfg.account + '|' + it.q + it.code + ' ' + it.group + ' ' + it.zone + ']';
        if (cfg.sendText && it.text) body += '[I' + clean(it.text) + ']';
    }
    if (cfg.timestamp) body += gmt(st.offset);
    return frame(body);
}
function clearTimer() { const t = context.get('timer'); if (t) clearTimeout(t); context.set('timer', null); }
function save() { context.set('st', st); node.status({ fill: st.inflight ? 'yellow' : 'green', shape: 'dot', text: (st.inflight ? 'waiting seq ' + st.inflight.seq + ' try ' + st.inflight.attempt : 'idle') + ' | queue ' + st.queue.length }); }
function transmit() {
    const it = st.inflight; it.attempt++;
    const f = build(it);
    clearTimer();
    context.set('timer', setTimeout(onTimeout, cfg.retryTimeoutMs));
    save();
    node.send([{ payload: Buffer.from(f, 'latin1'), host: cfg.host, port: cfg.port, dc09: { seq: it.seq, type: it.type } },
               { topic: 'TX', payload: { time: new Date().toISOString(), seq: it.seq, attempt: it.attempt, frame: JSON.stringify(f) } }]);
}
function pump() { if (!st.inflight && st.queue.length) { st.inflight = st.queue.shift(); st.inflight.attempt = 0; transmit(); } else save(); }
function finish(result, lvl) { clearTimer(); const it = st.inflight; st.inflight = null; log(lvl || 'RESULT', result, { seq: it && it.seq, event: it }); pump(); }
function onTimeout() {
    context.set('timer', null);
    if (!st.inflight) return;
    if (st.inflight.attempt < cfg.maxAttempts) { log('RETRY', 'no response, retrying', { seq: st.inflight.seq }); transmit(); }
    else finish('FAILED - no response after ' + st.inflight.attempt + ' attempts', 'FAIL');
}

switch (msg.topic) {
case 'event': {
    const e = msg.payload;
    if (!/^[136]$/.test(e.q) || !/^\d{3}$/.test(e.code) || !/^\d{2}$/.test(e.group) || !/^\d{3}$/.test(e.zone)) { node.error('Bad Contact ID event', msg); return null; }
    if (st.queue.length >= cfg.maxQueue) { st.queue.shift(); log('WARN', 'queue full, dropped oldest'); }
    st.queue.push({ type: 'CID', seq: nextSeq(), q: e.q, code: e.code, group: e.group, zone: e.zone, text: e.text });
    pump(); break;
}
case 'heartbeat':
    if (st.inflight || st.queue.length) return null;  // link is busy -> real traffic supervises it
    st.queue.push({ type: 'NULL', seq: '0000' }); pump(); break;
case 'response': {
    if (!st.inflight) return null;
    const r = unwrap(msg.payload);
    if (!r.ok) { log('WARN', 'bad response ignored: ' + r.err, { raw: r.raw }); return null; }
    if (r.seq !== st.inflight.seq && r.id !== 'NAK') { log('WARN', 'response for other seq ' + r.seq + ' ignored'); return null; }
    if (r.id === 'ACK' || r.id === 'RSP') { finish('ACK seq ' + r.seq, 'ACK'); }
    else if (r.id === 'NAK') {
        if (r.ts) {   // sync clock to receiver GMT
            const m = r.ts.match(/_(\d\d):(\d\d):(\d\d),(\d\d)-(\d\d)-(\d{4})/);
            st.offset = Date.UTC(+m[6], +m[4] - 1, +m[5], +m[1], +m[2], +m[3]) - Date.now();
        }
        if (st.inflight.attempt < cfg.maxAttempts) { log('NAK', 'NAK - resend with corrected timestamp', { offsetMs: st.offset }); transmit(); }
        else finish('FAILED - NAK x' + st.inflight.attempt, 'FAIL');
    }
    else if (r.id === 'DUH') finish('DUH - receiver cannot process, dropped', 'FAIL');
    else log('WARN', 'unknown response ' + r.id);
    break;
}
case 'reset':
    clearTimer(); st.queue = []; st.inflight = null; st.offset = 0; save(); log('INFO', 'sender reset'); break;
}
return null;

