function hex(v,w){return v.toString(16).toUpperCase().padStart(w,'0');}
function gmt(offsetMs){const d=new Date(Date.now()+(offsetMs||0));const p=x=>String(x).padStart(2,'0');return '_'+p(d.getUTCHours())+':'+p(d.getUTCMinutes())+':'+p(d.getUTCSeconds())+','+p(d.getUTCMonth()+1)+'-'+p(d.getUTCDate())+'-'+d.getUTCFullYear();}
function frame(body){return '\n'+crc16(body)+'0'+hex(body.length,3)+body+'\r';}
// DC-09 body regex: "id" seq [Rrcvr] Lpref [#acct|A0] [data] [ext]... [timestamp]
const RX=/^"(\*?[A-Z0-9-]+)"(\d{4})(R[0-9A-F]{1,6})?(L[0-9A-F]{1,6})(#[0-9A-F]{3,16}|A0)?\[([^\]]*)\]((?:\[[^\]]*\])*)(_\d\d:\d\d:\d\d,\d\d-\d\d-\d{4})?$/i;
function unwrap(raw){const s=String(raw).replace(/^[\r\n]+/,'').replace(/[\r\n]+$/,'');
  if(s.length<9)return {ok:false,err:'too short',raw:s};
  const crc=s.slice(0,4).toUpperCase(),len=s.slice(4,8),body=s.slice(8);
  if(crc16(body)!==crc)return {ok:false,err:'CRC mismatch (got '+crc+', calc '+crc16(body)+')',raw:s};
  if(parseInt(len,16)!==body.length)return {ok:false,err:'length mismatch',raw:s};
  const m=body.match(RX); if(!m)return {ok:false,err:'malformed frame',raw:s};
  return {ok:true,id:m[1],seq:m[2],rcvr:m[3]||'',pref:m[4],acct:m[5]||'',data:m[6],ext:m[7]||'',ts:m[8]||'',body};}

// ===== Mock DC-09 Central Station Receiver (for testing only) =====
// flow.mockMode: 'ack' (default) | 'nak' | 'duh' | 'silent'
const CID = {'100':'Medical','110':'Fire Alarm','111':'Smoke','113':'Waterflow','114':'Heat','115':'Pull Station',
 '120':'Panic','121':'Duress','130':'Burglary','137':'Tamper','140':'General Alarm','151':'Gas Detected','154':'Water Leakage',
 '158':'High Temp','159':'Low Temp','200':'Fire Supervisory','300':'System Trouble','301':'AC Loss','302':'Low Battery',
 '350':'Comm Trouble','373':'Fire Loop Trouble','380':'Sensor Trouble','383':'Sensor Tamper','401':'Open/Close by User',
 '570':'Zone Bypass','601':'Manual Test','602':'Periodic Test'};
const r = unwrap(msg.payload);
if (!r.ok) { node.warn('CSR discard (no reply): ' + r.err); return [null, { topic: 'DISCARD', payload: r }]; }
const mode = flow.get('mockMode') || 'ack';
const supported = ['ADM-CID', 'SIA-DCS', 'NULL'];
let reply;
if (mode === 'silent') reply = null;
else if (mode === 'nak') reply = '"NAK"0000R0L0A0[]' + gmt();
else if (mode === 'duh' || !supported.includes(r.id)) reply = '"DUH"' + r.seq + r.rcvr + r.pref + r.acct + '[]';
else reply = '"ACK"' + r.seq + r.rcvr + r.pref + r.acct + '[]';

let decoded = { id: r.id, seq: r.seq, rcvr: r.rcvr, pref: r.pref, acct: r.acct, ts: r.ts, ext: r.ext, reply: reply ? reply.slice(1, 4) : 'none' };
if (r.id === 'ADM-CID') {
    const m = r.data.match(/^#?([0-9A-F]+)\|([136])(\d{3}) (\d{2}) (\d{3})$/i);
    if (m) Object.assign(decoded, { event: (m[2] === '1' ? 'E' : m[2] === '3' ? 'R' : 'P') + m[3], desc: (CID[m[3]] || 'Code ' + m[3]) + (m[2] === '3' ? ' RESTORE' : ''), group: m[4], zone: m[5] });
}
node.status({ fill: 'blue', shape: 'dot', text: r.id + ' ' + r.seq + ' -> ' + decoded.reply });
const out = reply ? { payload: Buffer.from(frame(reply), 'latin1'), _session: msg._session } : null;
return [out, { topic: 'RX ' + r.id, payload: decoded }];

