            { dev: 'D', start: 100, words: 12 },   // D100..D111  counters, speed, codes
            { dev: 'D', start: 130, words: 2 },    // D130..D131  consumables
            { dev: 'D', start: 200, words: 16 },   // D200..D215  OCR / barcode ASCII
            { dev: 'M', start: 0, words: 1 }       // M0..M15     status bits
        ]
