// ---------- batch (started/ended from the dashboard, or followed from the PLC batch_no tag) ----------
const q = s => s === null || s === undefined ? 'NULL' : typeof s === 'number' ? (isFinite(s) ? String(s) : 'NULL') : "'" + String(s).replace(/'/g, "''").slice(0, 200) + "'";
