@media print{@page{size:A4;margin:12mm}body{background:#fff;font-size:11px}main{padding:0;max-width:none}.noprint{display:none}.card,.meta div,.kpi{border:.5px solid #d2d2d7;border-radius:10px}.kpi b{font-size:20px}h1{font-size:26px}.t td,.t th{padding:4px 8px 4px 0}}
`;
const W = 'FROM items WHERE batch = $1 AND ts >= $2 AND ts < $3';
const ask = (step, sql, params) => { R.step = step; msg.topic = sql; msg.payload = params; return [msg, null]; };
const win = () => [R.b.batch, R.b.start * 1000, (R.b.end ? R.b.end + 1 : Math.floor(Date.now() / 1000) + 1) * 1000];

function page(title, body) {
    msg.payload = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body><main>' + body + '</main></body></html>';
    msg.headers = { 'content-type': 'text/html; charset=utf-8' };
    return [null, msg];
}

switch (R.step) {
case 'start': {
    const id = parseInt(msg.req.query.id, 10);
    if (!id) { msg.statusCode = 400; return page('Report', '<h1>Batch report</h1><p class="muted">Open a report from <b>Batches</b> on the dashboard.</p>'); }
    return ask('batch', 'SELECT * FROM batches WHERE id = $1', [id]);
}
case 'batch':
    if (!msg.payload.length) { msg.statusCode = 404; return page('Report', '<h1>Batch not found</h1><p class="muted"><a href="/labeller">Back to dashboard</a></p>'); }
    R.b = msg.payload[0];
    return ask('sum', 'SELECT COUNT(*) n, SUM(ok) ok, MIN(ts) t0, MAX(ts) t1, SUM(est) est, SUM(sim) sim, MIN(bseq) s0, MAX(bseq) s1 ' + W, win());
case 'sum':
    R.sum = msg.payload[0];
    return ask('ends', 'SELECT * FROM (SELECT tid, code, ts ' + W + ' ORDER BY ts ASC LIMIT 1) UNION ALL SELECT * FROM (SELECT tid, code, ts FROM items WHERE batch = $4 AND ts >= $5 AND ts < $6 ORDER BY ts DESC LIMIT 1)', [...win(), ...win()]);
case 'ends':
    R.ends = msg.payload;
    return ask('reasons', 'SELECT reason, COUNT(*) n ' + W + ' AND ok = 0 GROUP BY reason ORDER BY n DESC', win());
case 'reasons':
    R.reasons = msg.payload;
    return ask('hourly', 'SELECT (ts / 3600000) * 3600000 h, COUNT(*) n, SUM(ok) ok ' + W + ' GROUP BY h ORDER BY h', win());
case 'hourly':
    R.hourly = msg.payload;
    return ask('people', 'SELECT shift, operator, COUNT(*) n, SUM(ok) ok, MIN(ts) t0, MAX(ts) t1 ' + W + ' GROUP BY shift, operator ORDER BY t0', win());
case 'people':
    R.people = msg.payload;
    return ask('rejects', 'SELECT ts, tid, reason, conf, offset, ocr, code, est ' + W + ' AND ok = 0 ORDER BY ts LIMIT 5000', win());
case 'rejects': R.rejects = msg.payload; break;
default: return null;
}

// ---------- render ----------
const b = R.b, s = R.sum || {}, now = Date.now();
const snap = flow.get('labSnap');
const live = !b.end && snap && snap.line.batch.id === b.batch && Math.floor(snap.line.batch.start / 1000) === b.start;
const counter = live ? snap.win.batch : { total: b.total, ok: b.ok, ng: b.ng, oee: b.oee };
const traced = s.n || 0, tOk = s.ok || 0, tNg = traced - tOk;
const total = traced || counter.total || 0, ok = traced ? tOk : counter.ok || 0, ng = total - ok;
const fmt = n => n === null || n === undefined ? '–' : Number(n).toLocaleString('en-US');
const dt = ms => ms ? new Date(ms).toLocaleString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '–';
const tm = ms => new Date(ms).toLocaleTimeString('en-GB');
const dur = sec => { if (!sec && sec !== 0) return '–'; const m = Math.round(sec / 60); return m < 60 ? m + ' min' : Math.floor(m / 60) + ' h ' + String(m % 60).padStart(2, '0') + ' min'; };
const endMs = b.end ? b.end * 1000 : now;
const pct = (a, c) => c ? (Math.round(1000 * a / c) / 10) + '%' : '–';

let recon;
if (!traced) recon = '<span class="badge warn">No item-level trace</span> This batch was recorded before per-product tracing was enabled; totals come from the batch counter.';
else {
    // serials run 1..N within a batch: anything not traced shows up as a hole in that sequence
    const before = Math.max(0, (s.s0 || 1) - 1);                 // counted before tracing started
    const gaps = Math.max(0, (s.s1 - s.s0 + 1) - traced);        // serials missing inside the range
    const pending = Math.max(0, counter.total - (s.s1 || 0));    // counted after the last saved record
    const lines = [];
    if (before) lines.push(fmt(before) + ' items (serial 1–' + fmt(before) + ') were counted before per-product tracing started and are not traced individually.');
    if (gaps) lines.push(fmt(gaps) + ' serial numbers between ' + fmt(s.s0) + ' and ' + fmt(s.s1) + ' have no trace record (e.g. a storage interruption).');
    if (pending && !(live && pending <= 400)) lines.push(fmt(pending) + ' items counted after the last traced serial ' + fmt(s.s1) + '.');
    if (!lines.length) recon = live && pending ? '<span class="badge info">In progress</span> Serials 1–' + fmt(s.s1) + ' fully traced; the latest ' + pending + ' items are saved within 60 s.'
        : '<span class="badge ok">Reconciled</span> Serials 1–' + fmt(s.s1) + ' are all traced and match the production counter (' + fmt(counter.total) + ').';
    else recon = '<span class="badge warn">Gaps</span> Traced ' + fmt(traced) + ' of ' + fmt(counter.total) + ' counted items.<br>' + lines.join('<br>');
}
const notes = [];
if (s.sim) notes.push('<div class="banner">SIMULATED DATA — ' + fmt(s.sim) + ' of ' + fmt(traced) + ' items came from the demo simulator, not the machine.</div>');
const estNote = s.est ? fmt(s.est) + ' items have inspection details estimated (no IV3/PLC detail available at the time).' : '';

const maxR = Math.max(1, ...R.reasons.map(r => r.n));
const csvUrl = '/labeller/api/items.csv?batch=' + encodeURIComponent(b.batch) + '&from=' + (b.start * 1000) + '&to=' + ((b.end ? b.end + 1 : Math.floor(now / 1000) + 1) * 1000);
const first = R.ends[0], last = R.ends[1] || R.ends[0];

let h = notes.join('') +
'<div class="top"><div><div class="eyebrow">Batch traceability report · ' + esc(cfg.line || '') + ' · ' + esc(cfg.machine || '') + '</div><h1>' + esc(b.batch) + '</h1><div class="sub">' + esc(b.product || '') + (b.note ? ' · ' + esc(b.note) : '') + '</div></div>' +
'<div class="tools noprint"><a class="btn" href="' + csvUrl + '">Download all items (CSV)</a><button class="btn primary" onclick="window.print()">Print / Save PDF</button></div></div>' +
'<div class="status ' + (b.end ? 'done' : 'live') + '">' + (b.end ? 'Completed' : 'In progress') + '</div>' +
'<section class="grid meta">' +
  [['Started', dt(b.start * 1000)], ['Ended', b.end ? dt(b.end * 1000) : 'Running'], ['Duration', dur((endMs - b.start * 1000) / 1000)], ['Run time', dur(live ? counter.runS : b.run_s)],
   ['Target', b.target ? fmt(b.target) + ' good' : '–'], ['Started by', esc(b.operator || '–')]].map(([k, v]) => '<div><span>' + k + '</span><b>' + v + '</b></div>').join('') +
'</section>' +
'<section class="grid kpis">' +
  [['Output', fmt(total)], ['Good', fmt(ok)], ['Rejects', fmt(ng) + ' <small>' + pct(ng, total) + '</small>'], ['OEE', counter.oee === null || counter.oee === undefined ? '–' : counter.oee + '%'], ['Target reached', b.target ? pct(ok, b.target) : '–']]
  .map(([k, v]) => '<div class="kpi"><span>' + k + '</span><b>' + v + '</b></div>').join('') +
'</section>' +
'<section class="card"><h2>Record integrity</h2><p>' + recon + '</p>' + (estNote ? '<p class="muted">' + estNote + '</p>' : '') +
(first ? '<table class="t"><tr><th></th><th>Trace ID</th><th>Barcode</th><th>Time</th></tr><tr><td class="muted">First item</td><td class="mono">' + esc(first.tid) + '</td><td class="mono">' + esc(first.code || '—') + '</td><td>' + dt(first.ts) + '</td></tr><tr><td class="muted">Last item</td><td class="mono">' + esc(last.tid) + '</td><td class="mono">' + esc(last.code || '—') + '</td><td>' + dt(last.ts) + '</td></tr></table>' : '') +
'</section>' +
'<div class="two"><section class="card"><h2>Reject reasons</h2>' + (R.reasons.length ? R.reasons.map(r => '<div class="bar"><span>' + esc(r.reason || 'Unclassified') + '</span><i><em style="width:' + (100 * r.n / maxR) + '%"></em></i><b>' + fmt(r.n) + ' · ' + pct(r.n, tNg) + '</b></div>').join('') : '<p class="muted">No rejects.</p>') + '</section>' +
'<section class="card"><h2>Shifts & operators</h2>' + (R.people.length ? '<table class="t"><tr><th>Shift</th><th>Operator</th><th>From</th><th>To</th><th class="r">Output</th><th class="r">Reject</th></tr>' +
  R.people.map(p => '<tr><td>' + esc(p.shift) + '</td><td>' + esc(p.operator) + '</td><td>' + tm(p.t0) + '</td><td>' + tm(p.t1) + '</td><td class="r">' + fmt(p.n) + '</td><td class="r">' + pct(p.n - p.ok, p.n) + '</td></tr>').join('') + '</table>' : '<p class="muted">–</p>') + '</section></div>' +
'<section class="card"><h2>Hourly production</h2>' + (R.hourly.length ? '<table class="t"><tr><th>Hour</th><th class="r">Output</th><th class="r">Good</th><th class="r">Rejects</th><th class="r">Reject rate</th></tr>' +
  R.hourly.map(x => '<tr><td>' + new Date(x.h).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) + '</td><td class="r">' + fmt(x.n) + '</td><td class="r">' + fmt(x.ok) + '</td><td class="r">' + fmt(x.n - x.ok) + '</td><td class="r">' + pct(x.n - x.ok, x.n) + '</td></tr>').join('') + '</table>' : '<p class="muted">–</p>') + '</section>' +
'<section class="card"><h2>Reject log <small>' + fmt(R.rejects.length) + (R.rejects.length >= 5000 ? ' (first 5,000 — full list in CSV)' : '') + '</small></h2>' + (R.rejects.length ? '<table class="t small"><tr><th>Time</th><th>Trace ID</th><th>Reason</th><th class="r">AI conf.</th><th class="r">Offset</th><th>OCR</th><th>Barcode</th></tr>' +
  R.rejects.map(x => '<tr><td>' + tm(x.ts) + '</td><td class="mono">' + esc(x.tid) + '</td><td>' + esc(x.reason) + (x.est ? ' <span class="est">est.</span>' : '') + '</td><td class="r">' + x.conf + '%</td><td class="r">' + (x.offset > 0 ? '+' : '') + x.offset + ' mm</td><td>' + esc(x.ocr) + '</td><td class="mono">' + esc(x.code || '—') + '</td></tr>').join('') + '</table>' : '<p class="muted">No rejects recorded.</p>') + '</section>' +
'<footer>Generated ' + dt(now) + ' · IRIV PiControl · read-only data collection · report covers records ' + dt(b.start * 1000) + ' – ' + (b.end ? dt(b.end * 1000) : 'now') + '</footer>';

return page('Batch ' + b.batch + ' · Traceability report', h);

// ===== Batch history -> browser (websocket) or CSV download (http) =====
const cfg = flow.get('labcfg') || { idealPpm: 120 };
const rows = (msg.payload || []).map(r => ({
    id: r.id, batch: r.batch, product: r.product, target: r.target, note: r.note, operator: r.operator,
    start: r.start * 1000, end: r.end ? r.end * 1000 : null, total: r.total, ok: r.ok, ng: r.ng,
    ngPct: r.total ? Math.round(1000 * r.ng / r.total) / 10 : 0, oee: r.oee, top: r.top_reason, runS: r.run_s
}));
if (msg.req) {
    const iso = t => t ? new Date(t).toLocaleString('sv-SE').slice(0, 19) : '';   // local time, sortable
    const cell = v => { const s = v === null || v === undefined ? '' : String(v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
    const head = ['batch', 'product', 'target', 'operator', 'start', 'end', 'output', 'good', 'rejects', 'reject_pct', 'oee_pct', 'top_reject', 'run_min', 'note'];
    const body = rows.map(r => [r.batch, r.product, r.target || '', r.operator, iso(r.start), iso(r.end), r.total, r.ok, r.ng, r.ngPct, r.oee, r.top, Math.round(r.runS / 60), r.note].map(cell).join(','));
    msg.payload = head.join(',') + '\n' + body.join('\n') + '\n';
    msg.headers = { 'content-type': 'text/csv; charset=utf-8', 'content-disposition': 'attachment; filename="batches-' + new Date().toISOString().slice(0, 10) + '.csv"' };
    return [null, msg];
}
return [{ _session: msg._session, payload: JSON.stringify({ type: 'batches', rows }) }, null];

msg.topic = 'SELECT batch,product,target,note,operator,start,end,total,ok,ng,run_s,oee,top_reason FROM batches ORDER BY start DESC LIMIT 5000';
msg.payload = [];
return msg;

// ===== Chat router + on-device answer engine =====
// in : websocket msg {type:'chat', id, text} | {type:'hello'}
// out1: reply to this browser only (msg._session kept)   out2: request for Claude (http request)
let m;
try { m = JSON.parse(msg.payload); } catch (e) { return null; }
const cfg = flow.get('labcfg') || {};
const S = flow.get('labSnap');
const H = flow.get('labHist');
const reply = (o) => ({ _session: msg._session, payload: JSON.stringify(o) });

if (m.type === 'hello') return [reply({ type: 'hist', hist: H || null }), null];
if (m.type !== 'chat' || !m.text) return null;
const text = String(m.text).slice(0, 500);

function local(q) {
    if (!S) return 'I am still starting up — give me a few seconds of data.';
    const s = q.toLowerCase();
    const w = S.win.shift, h = S.win.hour, L = S.line;
    const tips = { 'Label skew': 'check the applicator peel plate and web tension', 'Missing label': 'check the label gap sensor and roll splice', 'Wrong label': 'verify the loaded roll matches the batch', 'OCR misread': 'check the printhead and date-code contrast', 'Barcode unreadable': 'clean the printhead and check the ribbon', 'Wrinkle / bubble': 'check wipe-down brush pressure', 'Cap / seal': 'check capper torque upstream' };
    const reasons = (x, n) => x.reasons.slice(0, n).map(([k, v]) => '• ' + k + ' — ' + v + ' (' + Math.round(100 * v / Math.max(1, x.ng)) + '%)').join('\n');
    const has = (...k) => k.some(x => x.length <= 3 ? new RegExp('\\b' + x + '\\b').test(s) : s.includes(x));   // short words must match whole words ('ng' not in 'going')
    const statusTxt = { running: 'running', stopped: 'stopped', fault: 'in **fault**' }[L.status];
    const est = S.feed.some(f => f.est) ? '\n\n_Inspection details are partly simulated until the IV3/PLC data is mapped._' : '';

    if (has('yesterday', 'week', '7 day', 'history', 'last days', 'compare')) {
        if (!H || !H.days || !H.days.length) return 'History builds up in the on-device database every minute. Ask me again after the line has run for a while.';
        const d = H.days.slice(-7).map(x => '• ' + x.day + ': ' + x.total.toLocaleString() + ' pcs, NG ' + x.ngPct + '%, OEE ' + x.oee + '%').join('\n');
        return '**Last ' + Math.min(7, H.days.length) + ' days**\n' + d;
    }
    if (has('oee', 'efficien', 'availability', 'performance')) {
        const loss = [['Availability', w.A], ['Performance', w.P], ['Quality', w.Q]].sort((a, b) => a[1] - b[1])[0];
        return '**OEE this shift is ' + w.oee + '%**\nAvailability ' + w.A + '% · Performance ' + w.P + '% · Quality ' + w.Q + '%\n\nBiggest loss is **' + loss[0] + '** (' + loss[1] + '%). Last hour OEE: ' + h.oee + '%.';
    }
    if (has('label') && has('left', 'remain', 'roll', 'run out', 'empty', 'change')) {
        const c = S.consum.label;
        return 'Label roll is at **' + c.pct + '%** (~' + c.left.toLocaleString() + ' labels)' + (c.mins !== null ? ', about **' + c.mins + ' min** at the current speed.' : '.') + (c.est ? '\n_Estimated from the product count._' : '');
    }
    if (has('ribbon')) {
        const c = S.consum.ribbon;
        return 'Ribbon is at **' + c.pct + '%**' + (c.mins !== null ? ', about **' + c.mins + ' min** left.' : '.') + (c.est ? '\n_Estimated from the product count._' : '');
    }
    if (has('what should', 'check', 'fix', 'recommend', 'action', 'advice', 'improve')) {
        const acts = S.insights.filter(i => i.sev !== 'good').map(i => '• **' + i.title + '** — ' + i.body);
        const top = w.reasons[0];
        if (!acts.length && top) acts.push('• Top reject this shift is **' + top[0] + '** — ' + (tips[top[0]] || 'inspect the station') + '.');
        return acts.length ? 'Here is what I would look at:\n' + acts.join('\n') : 'Nothing needs attention right now — the line is stable.';
    }
    if (has('batch', 'lot')) {
        if (!L.batch.id) return 'No batch is running. Start one from **Batches → New batch**.';
        const b = S.win.batch, tgt = L.batch.target;
        let t = 'Batch **' + L.batch.id + '** (' + L.batch.product + '), started ' + new Date(L.batch.start).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ': ' + b.total.toLocaleString() + ' pcs, ' + b.ng + ' rejects (' + b.ngPct + '%), OEE ' + b.oee + '%.';
        if (tgt) { const left = Math.max(0, tgt - b.ok); t += '\nTarget ' + tgt.toLocaleString() + ' good — ' + Math.min(100, Math.round(100 * b.ok / tgt)) + '% done' + (left && L.speed > 5 ? ', about **' + Math.round(left / L.speed) + ' min** to go.' : '.'); }
        return t;
    }
    if (has('last', 'latest', 'recent')) {
        const f = S.feed.find(x => !x.ok);
        if (!f) return 'No recent rejects in the feed.';
        const ago = Math.round((Date.now() - f.t) / 1000);
        return 'Last reject was **#' + f.seq + '**, ' + ago + ' s ago: **' + f.reason + '** (AI confidence ' + f.conf + '%).\nOCR "' + f.ocr + '", code ' + (f.code || 'unreadable') + ', label offset ' + f.offset + ' mm.' + (f.est ? '\n_Classification simulated._' : '');
    }
    if (has('reject', 'ng', 'defect', 'quality', 'fail', 'why')) {
        if (!w.ng) return 'No rejects so far this shift. ' + w.total.toLocaleString() + ' good of ' + w.total.toLocaleString() + '.';
        const top = w.reasons[0];
        return '**' + w.ng + ' rejects this shift (' + w.ngPct + '%)**, last hour ' + h.ngPct + '%.\n' + reasons(w, 4) + '\n\nMain cause is **' + top[0].toLowerCase() + '** — ' + (tips[top[0]] || 'inspect the station') + '.' + est;
    }
    if (has('alert', 'alarm', 'warning', 'predict', 'problem')) {
        if (!S.alerts.length) return 'No active alerts. Label roll ' + S.consum.label.pct + '%, ribbon ' + S.consum.ribbon.pct + '%.';
        return S.alerts.map(a => '• **' + a.title + '** — ' + a.body).join('\n');
    }
    if (has('speed', 'rate', 'ppm', 'bpm', 'fast', 'slow')) return 'Running at **' + L.speed + ' PPM** (rated ' + L.ideal + ' PPM). Performance this hour: ' + h.P + '%.';
    if (has('shift', 'operator', 'who')) return 'Shift **' + L.shift.name + '** (' + L.shift.start + '–' + L.shift.end + '), operator **' + L.operator + '**. ' + w.total.toLocaleString() + ' pcs so far.';
    if (has('how many', 'output', 'count', 'produc', 'total')) return '**' + w.total.toLocaleString() + ' pcs** this shift — ' + w.ok.toLocaleString() + ' good, ' + w.ng + ' rejected. Last hour: ' + h.total.toLocaleString() + ' pcs.';
    if (has('hello', 'hi ', 'hey', 'help', 'what can')) return 'Hi — I am watching ' + L.name + '. Ask me about OEE, rejects and their causes, what to check, label roll or ribbon, speed, batch or shift, alerts, or the last 7 days.';
    // summary
    return '**' + L.name + ' is ' + statusTxt + '** at ' + L.speed + ' PPM.\nShift ' + L.shift.name + ': ' + w.total.toLocaleString() + ' pcs, NG ' + w.ngPct + '%, OEE ' + w.oee + '%.' + (S.alerts.length ? '\nActive alert: ' + S.alerts[0].title + '.' : '\nNo active alerts.');
}

const answer = local(text);

// session history (bounded: 10 sessions x 6 turns)
const hist = flow.get('chatHist') || {};
const sid = msg._session && msg._session.id || 'x';
const sess = hist[sid] || { t: 0, turns: [] };
sess.t = Date.now();
const prior = sess.turns.slice(-6);

const key = env.get('ANTHROPIC_API_KEY');
if (cfg.chatProvider === 'claude' && key) {
    const system = 'You are the assistant built into an industrial labelling and inspection line (Solo labeller with KEYENCE IV3 AI vision: OCR, 1D/2D code, label position, missing/wrong label, cap/seal, AI defect detection). ' +
        'You only observe; you cannot control the machine. Answer operators and managers briefly (max ~120 words), plain language, use the live data below, give concrete checks. Use **bold** sparingly, bullets with "• ". If data is marked est:true it is simulated. ' +
        '\n\nLIVE SNAPSHOT (JSON):\n' + JSON.stringify({ line: S && S.line, shift: S && S.win.shift, hour: S && S.win.hour, batch: S && S.win.batch, alerts: S && S.alerts, insights: S && S.insights, consumables: S && S.consum, recent: S && S.feed.slice(0, 6), days: H && H.days && H.days.slice(-7) });
    const req = {
        _session: msg._session, chatId: m.id, localAnswer: answer, userText: text,
        url: 'https://api.anthropic.com/v1/messages', method: 'POST', requestTimeout: 20000,
        headers: { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        payload: { model: cfg.claudeModel, max_tokens: 400, system, messages: [...prior, { role: 'user', content: text }] }
    };
    return [reply({ type: 'typing', id: m.id }), req];
}

sess.turns = [...prior, { role: 'user', content: text }, { role: 'assistant', content: answer }].slice(-6);
hist[sid] = sess;
const ids = Object.keys(hist).sort((a, b) => hist[b].t - hist[a].t);
ids.slice(10).forEach(k => delete hist[k]);
flow.set('chatHist', hist);
return [reply({ type: 'chat', id: m.id, text: answer, provider: 'local' }), null];

// ===== Claude reply -> browser (falls back to the on-device answer on any error) =====
let text = null, provider = 'claude';
const p = msg.payload;
if (!msg.error && msg.statusCode === 200 && p && Array.isArray(p.content)) {
    text = p.content.filter(c => c.type === 'text').map(c => c.text).join('\n').trim();
}
if (!text) {
    provider = 'local';
    text = msg.localAnswer || 'Sorry, I could not answer that.';
    node.warn('Claude unavailable (' + (msg.error ? (msg.error.message || msg.error) : 'HTTP ' + msg.statusCode + ' ' + JSON.stringify(p && p.error || '')) + ') - used on-device answer');
}
const hist = flow.get('chatHist') || {};
const sid = msg._session && msg._session.id || 'x';
const sess = hist[sid] || { t: 0, turns: [] };
sess.t = Date.now();
sess.turns = [...sess.turns, { role: 'user', content: msg.userText }, { role: 'assistant', content: text }].slice(-6);
hist[sid] = sess;
Object.keys(hist).sort((a, b) => hist[b].t - hist[a].t).slice(10).forEach(k => delete hist[k]);
flow.set('chatHist', hist);
return { _session: msg._session, payload: JSON.stringify({ type: 'chat', id: msg.chatId, text, provider }) };

// A failed statement inside BEGIN..COMMIT leaves the transaction open and blocks every later write.
// Roll it back once (never loop on a failed ROLLBACK itself).
if (/^\s*ROLLBACK/i.test(msg.topic || '')) return null;
node.warn('SQLite write failed, rolled back: ' + (msg.error && msg.error.message));
return { topic: 'ROLLBACK;' };
